const setPaymentTransactionExternalRef = `-- name: SetPaymentTransactionExternalRef :execrows
UPDATE transaction SET idempotency_key = $2, updated_at = NOW()
WHERE id = $1 AND idempotency_key IS NULL
`

type SetPaymentTransactionExternalRefParams struct {
	ID             uuid.UUID `json:"id"`
	IdempotencyKey *string   `json:"idempotency_key"`
}

// Repurposes the (otherwise-unused-at-creation) idempotency_key column to
// remember a gateway's own opaque transaction id (Payme's CreateTransaction
// params.id), so later Perform/Cancel/Check calls — which only carry that
// opaque id, not our account/order_id — can resolve back to our row.
func (q *Queries) SetPaymentTransactionExternalRef(ctx context.Context, arg SetPaymentTransactionExternalRefParams) (int64, error) {
	result, err := q.db.Exec(ctx, setPaymentTransactionExternalRef, arg.ID, arg.IdempotencyKey)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setPaymentTransactionStatus = `-- name: SetPaymentTransactionStatus :execrows
UPDATE transaction SET status = $1, updated_at = NOW()
WHERE id = $2 AND status = $3
`

type SetPaymentTransactionStatusParams struct {
	Status         bool      `json:"status"`
	ID             uuid.UUID `json:"id"`
	ExpectedStatus bool      `json:"expected_status"`
}

// Guarded toggle (mirrors Django TransactionModel.objects.filter(pk=, status=<expected>).update(status=<new>)).
func (q *Queries) SetPaymentTransactionStatus(ctx context.Context, arg SetPaymentTransactionStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setPaymentTransactionStatus, arg.Status, arg.ID, arg.ExpectedStatus)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sumPaidPaymentOrderNetForOwner = `-- name: SumPaidPaymentOrderNetForOwner :one
SELECT COALESCE(SUM(net_amount), 0)::numeric AS total FROM payment_order
WHERE owner_id = $1 AND status = 'paid' AND deleted_at IS NULL
`

// Total bot-earned net income across all projects (withdrawal eligibility base).
func (q *Queries) SumPaidPaymentOrderNetForOwner(ctx context.Context, ownerID uuid.UUID) (pgtype.Numeric, error) {
	row := q.db.QueryRow(ctx, sumPaidPaymentOrderNetForOwner, ownerID)
	var total pgtype.Numeric
	err := row.Scan(&total)
	return total, err
}

const sumPaymentEarningsForOwner = `-- name: SumPaymentEarningsForOwner :one
SELECT
    COALESCE(SUM(net_amount), 0)::numeric AS total_earned,
    COALESCE(SUM(commission), 0)::numeric AS total_commission
FROM payment_order
WHERE owner_id = $1 AND status = 'paid' AND deleted_at IS NULL
`

type SumPaymentEarningsForOwnerRow struct {
	TotalEarned     pgtype.Numeric `json:"total_earned"`
	TotalCommission pgtype.Numeric `json:"total_commission"`
}

func (q *Queries) SumPaymentEarningsForOwner(ctx context.Context, ownerID uuid.UUID) (SumPaymentEarningsForOwnerRow, error) {
	row := q.db.QueryRow(ctx, sumPaymentEarningsForOwner, ownerID)
	var i SumPaymentEarningsForOwnerRow
	err := row.Scan(&i.TotalEarned, &i.TotalCommission)
	return i, err
}

const sumReservedPaymentWithdrawals = `-- name: SumReservedPaymentWithdrawals :one
SELECT COALESCE(SUM(amount), 0)::numeric AS total FROM payment_withdrawal_request
WHERE user_id = $1 AND status IN ('pending', 'approved')
`

// pending + approved withdrawals reserve bot income until reviewed/paid out.
func (q *Queries) SumReservedPaymentWithdrawals(ctx context.Context, userID uuid.UUID) (pgtype.Numeric, error) {
	row := q.db.QueryRow(ctx, sumReservedPaymentWithdrawals, userID)
	var total pgtype.Numeric
	err := row.Scan(&total)
	return total, err
}
